1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isNeighbourOf = (cell: Cell, candidate: Cell): boolean =>
7	  !isSameCell(cell, candidate) &&
8	  Math.abs(candidate[0] - cell[0]) <= 1 &&
9	  Math.abs(candidate[1] - cell[1]) <= 1;
10	
11	const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
12	  liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
13	
14	const survives = (cell: Cell, liveCells: Cell[]): boolean =>
15	  countLiveNeighbours(cell, liveCells) === 3;
16	
17	const OFFSETS = [-1, 0, 1];
18	
19	const candidateCells = (liveCells: Cell[]): Cell[] => {
20	  const seen = new Map<string, Cell>();
21	
22	  for (const [x, y] of liveCells) {
23	    for (const offsetX of OFFSETS) {
24	      for (const offsetY of OFFSETS) {
25	        const candidate: Cell = [x + offsetX, y + offsetY];
26	        seen.set(`${candidate[0]},${candidate[1]}`, candidate);
27	      }
28	    }
29	  }
30	
31	  return [...seen.values()];
32	};
33	
34	export function nextGeneration(liveCells: Cell[]): Cell[] {
35	  return candidateCells(liveCells).filter((cell) => survives(cell, liveCells));
36	}
37

1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - next generation", () => {
5	  it("should return an empty grid for an empty grid — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should kill a single lone cell (0 neighbors) — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("Rule 1 Underpopulation: should kill both cells that have 1 neighbor each — [(0,1), (1,1)] → []", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 1],
15	        [1, 1],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("Rule 2 Survival: should keep a live cell with 3 live neighbors alive — center (1,1) survives", () => {
20	    // Gen 0: ### on the top row, plus the live centre cell (1,1).
21	    // (1,1) is live and has exactly 3 live neighbours: (0,0), (1,0), (2,0).
22	    const result = nextGeneration([
23	      [0, 0],
24	      [1, 0],
25	      [2, 0],
26	      [1, 1],
27	    ]);
28	
29	    expect(result).toContainEqual([1, 1]);
30	  });
31	  it("Rule 3 Overpopulation: should kill a live cell with 4 live neighbors — center (1,1) dies", () => {
32	    // Gen 0: the live centre (1,1) surrounded by the four corners of its
33	    // 3x3 box, giving it exactly 4 live neighbours.
34	    const result = nextGeneration([
35	      [0, 0],
36	      [2, 0],
37	      [1, 1],
38	      [0, 2],
39	      [2, 2],
40	    ]);
41	
42	    expect(result).not.toContainEqual([1, 1]);
43	  });
44	  it("Rule 4 Reproduction: should bring a dead cell with exactly 3 live neighbors to life — (1,1) becomes alive", () => {
45	    // Gen 0: an L-shaped triomino. The dead cell (1,1) is adjacent to all
46	    // three live cells, so it has exactly 3 live neighbours and is born.
47	    const result = nextGeneration([
48	      [0, 0],
49	      [1, 0],
50	      [0, 1],
51	    ]);
52	
53	    expect(result).toContainEqual([1, 1]);
54	  });
